from typing import List
import bisect

class Solution:
    def lastStoneWeight(self, stones: List[int]) -> int:
        stones = sorted(stones)
        while len(stones) > 1:
            x = stones.pop()
            y = stones.pop()
            if x != y:
                # Maintain sorted order after the smash.
                bisect.insort(stones, x - y)
        return stones[0] if stones else 0

